registerEnumType(PublicDocMode, {
  name: 'PublicDocMode',
  description: 'The mode which the public doc default in',
});

function toDomainDocRole(role: DocRole) {
  const native = toNativeExplicitDocGrantRole(role);
  return native === 'reader' ||
    native === 'commenter' ||
    native === 'editor' ||
    native === 'manager' ||
    native === 'owner'
    ? native
    : undefined;
}

